import json, pathlib, hashlib, re
root=pathlib.Path('.')
coverage=json.load(open('changes/p99-nz-coverage/page-coverage.json'))
rows=[]
def add(title,facets,gaps):
 r=next(x for x in coverage if x['title']==title)
 sources=[]
 for s in r['scripts']:
  if not s.get('file'):
   sources.append(s);continue
  p=root/s['file']; b=p.read_bytes(); maintained=[]
  for m in root.glob('maintained/lua/*/'+s['key']+'.lua'):
   mb=m.read_bytes();maintained.append({'file':str(m),'sha256':hashlib.sha256(mb).hexdigest(),'equals_effective':mb==b})
  sources.append({**s,'sha256':hashlib.sha256(b).hexdigest(),'maintained':maintained})
 ep=root/r['evidence']['cachePath'];assert hashlib.sha256(ep.read_bytes()).hexdigest()==r['evidence']['sha256']
 rows.append({'title':title,'review_status':'source_facets_reviewed_path_open','evidence':r['evidence'],'sources':sources,'verified_facets':facets,'unresolved':gaps+['Runtime settlement, repeated/partial/extra offers, actual NPC/loot acquisition and rendered UI not verified in this source-only workspace.'],'verification':{'source':'Full cached quest page and canonical available Lua read; legacy alias sources only hashed unless expressly stated; named item IDs resolved against exported items','runtime':'not_run','ui':'not_run','connected_chain':'not_run'}})
